REVOKE INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON public.user_roles FROM anon,authenticated; REVOKE INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON public.tickets FROM anon,authenticated; REVOKE INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON public.profiles FROM anon,authenticated; GRANT UPDATE(display_name,city,mediums,photo) ON public.profiles TO authenticated; REVOKE INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER ON public.rooms,public.pieces,public.services,public.events FROM anon; REVOKE EXECUTE ON FUNCTION public.reserve_ticket(text),public.complete_registration(jsonb),public.check_in_ticket(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reserve_ticket(text),public.complete_registration(jsonb),public.check_in_ticket(uuid) TO authenticated;